package com.omnistyle

import com.facebook.react.bridge.ReadableArray
import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.viewmanagers.OmniCameraViewManagerDelegate
import com.facebook.react.viewmanagers.OmniCameraViewManagerInterface

/**
 * Bridge between Fabric and `OmniCameraView`: props, commands and events.
 * `OmniCameraViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/camera/native/OmniCameraViewNativeComponent.ts`.
 */
@ReactModule(name = OmniCameraViewManager.NAME)
class OmniCameraViewManager :
  SimpleViewManager<OmniCameraView>(),
  OmniCameraViewManagerInterface<OmniCameraView> {

  private val delegate = OmniCameraViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<OmniCameraView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): OmniCameraView = OmniCameraView(context)

  override fun onDropViewInstance(view: OmniCameraView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  override fun setFacing(view: OmniCameraView, value: String?) = view.setFacing(value)

  override fun setActive(view: OmniCameraView, value: Boolean) = view.setActive(value)

  override fun setFlash(view: OmniCameraView, value: String?) = view.setFlash(value)

  override fun setTorch(view: OmniCameraView, value: Boolean) = view.setTorch(value)

  override fun setZoom(view: OmniCameraView, value: Float) = view.setZoom(value)

  override fun setZoomGesture(view: OmniCameraView, value: Boolean) = view.setZoomGesture(value)

  override fun setFocusGesture(view: OmniCameraView, value: Boolean) = view.setFocusGesture(value)

  override fun setVideo(view: OmniCameraView, value: Boolean) = view.setVideo(value)

  override fun setAudio(view: OmniCameraView, value: Boolean) = view.setAudio(value)

  override fun setCodeScanner(view: OmniCameraView, value: Boolean) = view.setCodeScanner(value)

  override fun setCodeTypes(view: OmniCameraView, value: ReadableArray?) = view.setCodeTypes(value)

  // ── commands ──

  override fun takePhoto(view: OmniCameraView, requestId: Int, flash: String) = view.takePhoto(requestId, flash)

  override fun startRecording(view: OmniCameraView, requestId: Int) = view.startRecording(requestId)

  override fun stopRecording(view: OmniCameraView, requestId: Int) = view.stopRecording(requestId)

  override fun requestPermission(view: OmniCameraView) = view.requestPermission()

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    OmniCameraView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "OmniCameraView"
  }
}
